"""Prepare full inactive coordinated copies and one review diff; never promote."""
from pathlib import Path
import difflib,json,hashlib
H=Path(__file__).resolve().parent;ROOT=H.parents[2];changes={}
def edit(path,fn):
 old=(ROOT/path).read_text();new=fn(old)
 assert new!=old,path
 changes[path]=(old,new)
edit('src/hooks/useAvailableContexts.ts',lambda s:s.replace('export type PortalContext = "b2b" | "technical" | "admin";', 'export type PortalContext = "b2b" | "technical" | "producer" | "admin";').replace('import { useContext', 'import { decodeC2Contexts, isC2ExternalScope } from "@/lib/authz/multiProfileContract";\nimport { useContext',1).replace('      const raw = (data ?? {})', '      if (isC2ExternalScope(roles)) decodeC2Contexts(data,user?.id ?? "",profile?.organization_id ?? "",roles);\n      const raw = (data ?? {})').replace('value === "admin" || value === "b2b" || value === "technical"','value === "admin" || value === "b2b" || value === "technical" || value === "producer"').replace('data: ready && (!requireFresh', 'data: ready && !result.isError && (!requireFresh'))
edit('src/lib/portalContext.ts',lambda s:s.replace('  b2b:','  producer: "/app",\n  b2b:',1).replace('const PORTAL_ROLES: AppRole[] = [','const PORTAL_ROLES: AppRole[] = [\n  "cliente_produtor",'))
edit('src/hooks/useMyPartner.ts',lambda s:s.replace('import { readCatalogCapabilities', 'import { decodeC2Partner, isC2ExternalScope } from "@/lib/authz/multiProfileContract";\nimport { readCatalogCapabilities',1).replace('const { roles, profile }','const { user, roles, profile }').replace('const role = roles.length === 1 ? roles[0] : null;', 'const role = isC2ExternalScope(roles) ? roles.includes("parceiro_b2b") ? "parceiro_b2b" : roles.includes("parceiro_b2b_tecnico") ? "parceiro_b2b_tecnico" : null : null;').replace('      const context = rawContext as Record<string, unknown>;', '      const context = decodeC2Partner(rawContext,user?.id ?? "",profile?.organization_id ?? "",roles);').replace('      const partner = rawPartner as Record<string, unknown>;', '      const partner = rawPartner as Record<string, unknown>;\n      if (partner.contract !== "C2_MULTIPROFILE_V1" || partner.actor_id !== user?.id || partner.tenant_id !== profile?.organization_id || JSON.stringify(partner.external_roles) !== JSON.stringify(context.external_roles)) throw new Error("partner_context_unavailable");'))
edit('src/components/guards/B2BRouteGuard.tsx',lambda s:s.replace('import { ReactNode', 'import { isC2ExternalScope } from "@/lib/authz/multiProfileContract";\nimport { ReactNode',1).replace('roles.length === 1 &&\n    (roles[0] === "parceiro_b2b" || roles[0] === "parceiro_b2b_tecnico")', 'isC2ExternalScope(roles) && roles.includes("parceiro_b2b")'))
edit('src/components/guards/AppPortalGuard.tsx',lambda s:s.replace('import { ReactNode','import { isC2ExternalScope } from "@/lib/authz/multiProfileContract";\nimport { ReactNode',1).replace('const isProducer = roles.includes("cliente_produtor");','const external = isC2ExternalScope(roles);\n  const isProducer = external ? data?.available_contexts.includes("producer") === true : roles.includes("cliente_produtor");').replace('const monitoredTechnical = isMonitoredConsultant', 'const monitoredTechnical = external || isMonitoredConsultant').replace('(isProducer || monitoredTechnical || authzLatchBlocked)', '(external || isProducer || monitoredTechnical || authzLatchBlocked)'))
edit('src/hooks/useAuth.tsx',lambda s:s.replace('import { b2bContextProbe', 'import { c2ContextProbe, isC2ExternalScope } from "@/lib/authz/multiProfileContract";\nimport { b2bContextProbe',1).replace('const b2bContextOnly = AUTHZ_CACHE_ROLLOUT_SCOPE === "b2b-context";', 'const b2bContextOnly = AUTHZ_CACHE_ROLLOUT_SCOPE === "b2b-context";\n  const cumulativeExternal = b2bContextOnly && isC2ExternalScope(roles);').replace('(roles.length === 1 && (roles[0] === "parceiro_b2b" || roles[0] === "parceiro_b2b_tecnico"))','cumulativeExternal').replace('        if (producerContextOnly) {', '        if (cumulativeExternal) {\n          const { data,error } = await supabase.rpc("get_my_available_portal_contexts");\n          if (error) throw new Error("c2_probe_unavailable");\n          return c2ContextProbe(data,user?.id ?? "",profile?.organization_id ?? "",roles);\n        }\n        if (producerContextOnly) {'))
edit('src/pages/SelecionarPortal.tsx',lambda s:s.replace('ctx === "technical" ? "Portal Técnico" : "Portal Parceiro B2B"','ctx === "technical" ? "Portal Técnico" : ctx === "producer" ? "Portal Cliente/Produtor" : "Portal Parceiro B2B"').replace('ctx === "technical" ? Sprout : Store','ctx === "technical" || ctx === "producer" ? Sprout : Store'))
helper=(H/'frontend/multiProfileContract.ts').read_text()
changes['src/lib/authz/multiProfileContract.ts']=('',helper)
out=H/'frontend/runtime-copies'
manifest=[];diff=[]
for path,(old,new) in changes.items():
 target=out/path;target.parent.mkdir(parents=True,exist_ok=True);target.write_text(new)
 manifest.append({'path':path,'baseline_sha256':hashlib.sha256(old.encode()).hexdigest(),'candidate_sha256':hashlib.sha256(new.encode()).hexdigest()})
 diff.extend(difflib.unified_diff(old.splitlines(True),new.splitlines(True),fromfile='a/'+path,tofile='b/'+path))
(H/'frontend/coordinated.patch').write_text(''.join(diff))
(H/'frontend/manifest.json').write_text(json.dumps(manifest,indent=2)+'\n')
print(f'Prepared {len(changes)} inactive frontend copies; runtime untouched')